import os, sys
sys.path.insert(0, os.path.join('.codex', 'skills', 'docx'))
from scripts.document import Document

# List unpacked tree
for root, dirs, files in os.walk('unpacked'):
    for f in files:
        p = os.path.join(root, f)
        print('FILE:', p)

doc = Document('unpacked')
xml = doc['word/document.xml'].dom

ns = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'

paras = xml.getElementsByTagNameNS(ns, 'p')
print('\nTOTAL PARAGRAPHS:', len(paras))

def para_text(p):
    texts = []
    for t in p.getElementsByTagNameNS(ns, 't'):
        texts.append(''.join(ch.data for ch in t.childNodes if ch.nodeType == ch.TEXT_NODE))
    return ''.join(texts)

def para_style(p):
    pPr = p.getElementsByTagNameNS(ns, 'pPr')
    if not pPr:
        return None
    styles = pPr[0].getElementsByTagNameNS(ns, 'pStyle')
    if not styles:
        return None
    return styles[0].getAttributeNS(ns, 'val')

for i, p in enumerate(paras):
    style = para_style(p)
    txt = para_text(p).strip()
    if txt or style:
        print(f'[{i}] style={style!r} text={txt[:90]!r}')

import sys
from xml.dom import minidom

path = "unpacked/word/document.xml"
dom = minidom.parse(path)

def get_text_runs(p):
    parts = []
    for r in p.getElementsByTagName("w:r"):
        for t in r.getElementsByTagName("w:t"):
            parts.append(t.firstChild.nodeValue if t.firstChild else "")
        for t in r.getElementsByTagName("w:delText"):
            parts.append(t.firstChild.nodeValue if t.firstChild else "")
    return "".join(parts)

paras = dom.getElementsByTagName("w:p")
for i, p in enumerate(paras):
    pPr = p.getElementsByTagName("w:pPr")
    style_val = None
    if pPr:
        styles = pPr[0].getElementsByTagName("w:pStyle")
        if styles and styles[0].getAttribute("w:val"):
            style_val = styles[0].getAttribute("w:val")
    text = get_text_runs(p).strip()
    if style_val and (style_val.startswith("Heading") or style_val in ("Title", "Subtitle")):
        runs = []
        for r in p.getElementsByTagName("w:r"):
            rpr = r.getElementsByTagName("w:rPr")
            rpr_xml = rpr[0].toxml() if rpr else "(no rPr)"
            runs.append((rpr_xml, r.toxml()))
        print(f"[{i}] pStyle={style_val!r} text={text!r} run_count={len(p.getElementsByTagName('w:r'))}")
        for j, (rpr_xml, rxml) in enumerate(runs):
            print(f"    run {j}: rPr={rpr_xml}")

import sys
import xml.etree.ElementTree as ET

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"

def q(name):
    return "{%s}%s" % (W, name)

for prefix, uri in [
    ("ve", "http://schemas.openxmlformats.org/markup-compatibility/2006"),
    ("o", "urn:schemas-microsoft-com:office:office"),
    ("r", "http://schemas.openxmlformats.org/officeDocument/2006/relationships"),
    ("v", "urn:schemas-microsoft-com:vml"),
    ("wp", "http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing"),
    ("w10", "urn:schemas-microsoft-com:office:word"),
]:
    ET.register_namespace(prefix, uri)


def para_text(p):
    return "".join((t.text or "") for t in p.iter(q("t"))).strip()


def main():
    path = sys.argv[1] if len(sys.argv) > 1 else "unpacked_q/word/document.xml"
    tree = ET.parse(path)
    body = tree.getroot().find(q("body"))

    # Headlines in this report are the full-uppercase standalone lines.
    headline_paras = []
    for p in body.iter(q("p")):
        tx = para_text(p)
        if tx and any(c.isalpha() for c in tx) and tx == tx.upper():
            headline_paras.append((p, tx))

    expected = {
        "EXECUTIVE SUMMARY",
        "FINANCIAL HIGHLIGHTS",
        "REVENUE BREAKDOWN BY SEGMENT",
        "KEY PERFORMANCE INDICATORS",
        "OPERATING EXPENSES",
        "Q1 2025 OUTLOOK",
        "RISK FACTORS",
    }
    found = {tx for _, tx in headline_paras}
    if found != expected:
        print("Unexpected headline set found:", sorted(found))
        sys.exit(2)

    # rPr children that must follow w:u per the OOXML schema.
    after_u = {
        "effect", "bdr", "shd", "fitText", "vertAlign", "rtl", "cs", "em",
        "lang", "eastAsianLayout", "specVanish", "oMath",
    }
    runs_changed = 0
    for p, _ in headline_paras:
        for r in p.findall(q("r")):
            rpr = r.find(q("rPr"))
            if rpr is None:
                rpr = ET.Element(q("rPr"))
                r.insert(0, rpr)
            if any(c.tag.rsplit("}", 1)[-1] == "u" for c in rpr):
                continue
            u = ET.Element(q("u"))
            u.set(q("val"), "single")
            pos = None
            for i, c in enumerate(list(rpr)):
                if c.tag.rsplit("}", 1)[-1] in after_u:
                    pos = i
                    break
            if pos is None:
                rpr.append(u)
            else:
                rpr.insert(pos, u)
            runs_changed += 1

    tree.write(path, encoding="ascii", xml_declaration=True)
    print("underlined %d headline paragraphs (%d text runs) in %s"
          % (len(headline_paras), runs_changed, path))


if __name__ == "__main__":
    main()

